import pulp

# Create the model
model = pulp.LpProblem("TSP_Sales_Representative", pulp.LpMinimize)

# Number of offices
n = 11

# Travel times between offices (symmetric)
dist = {
    (1, 2): 40.4, (1, 3): 77.4, (1, 4): 13.6, (1, 5): 135.1, (1, 6): 156.2, (1, 7): 201.8, (1, 8): 148.5, (1, 9): 191.4, (1, 10): 111.0, (1, 11): 179.6,
    (2, 3): 55.9, (2, 4): 32.4, (2, 5): 97.7, (2, 6): 132.8, (2, 7): 171.4, (2, 8): 110.4, (2, 9): 153.8, (2, 10): 116.6, (2, 11): 150.9,
    (3, 4): 78.5, (3, 5): 73.1, (3, 6): 79.2, (3, 7): 125.3, (3, 8): 87.4, (3, 9): 125.3, (3, 10): 76.6, (3, 11): 102.5,
    (4, 5): 129.8, (4, 6): 157.7, (4, 7): 200.6, (4, 8): 142.6, (4, 9): 186.0, (4, 10): 120.7, (4, 11): 179.0,
    (5, 6): 77.1, (5, 7): 85.2, (5, 8): 14.3, (5, 9): 56.3, (5, 10): 140.6, (5, 11): 72.8,
    (6, 7): 57.1, (6, 8): 83.5, (6, 9): 93.4, (6, 10): 99.4, (6, 11): 33.5,
    (7, 8): 81.7, (7, 9): 62.0, (7, 10): 156.5, (7, 11): 24.2,
    (8, 9): 43.7, (8, 10): 153.7, (8, 11): 73.2,
    (9, 10): 182.3, (9, 11): 67.7,
    (10, 11): 132.8
}

# Create symmetric distance matrix
d = {}
for i in range(1, n+1):
    for j in range(1, n+1):
        if i == j:
            d[(i, j)] = 0
        elif i < j:
            d[(i, j)] = dist[(i, j)]
        else:
            d[(i, j)] = dist[(j, i)]

# Decision variables: x[i][j] = 1 if travel from i to j
x = {}
for i in range(1, n+1):
    for j in range(1, n+1):
        if i != j:
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", cat='Binary')

# Subtour elimination variables: u[i] = position of node i in tour (MTZ formulation)
u = {}
for i in range(1, n+1):
    u[i] = pulp.LpVariable(f"u_{i}", lowBound=1, upBound=n, cat='Continuous')

# Objective: minimize total travel time
model += pulp.lpSum(d[(i, j)] * x[(i, j)] for i in range(1, n+1) for j in range(1, n+1) if i != j)

# Constraints: each office is exited exactly once
for i in range(1, n+1):
    model += pulp.lpSum(x[(i, j)] for j in range(1, n+1) if i != j) == 1

# Constraints: each office is entered exactly once
for j in range(1, n+1):
    model += pulp.lpSum(x[(i, j)] for i in range(1, n+1) if i != j) == 1

# Subtour elimination constraints (MTZ)
for i in range(2, n+1):
    for j in range(2, n+1):
        if i != j:
            model += u[i] - u[j] + n * x[(i, j)] <= n - 1

# Solve with HiGHS
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total travel time: {pulp.value(model.objective):.2f} minutes")

# Extract and print the tour
if model.status == pulp.LpStatusOptimal:
    tour = []
    current = 1
    visited = set()
    for _ in range(n):
        tour.append(current)
        visited.add(current)
        for j in range(1, n+1):
            if j != current and j not in visited and pulp.value(x[(current, j)]) > 0.5:
                current = j
                break
    tour.append(1)  # Return to start

    print(f"Optimal tour: {' -> '.join(map(str, tour))}")

    # Verify total distance
    total = 0
    for i in range(len(tour)-1):
        total += d[(tour[i], tour[i+1])]
    print(f"Verified total: {total:.2f} minutes")
